    AS row(code text, display_name text, manufacturer text, manufacturer_family text)
), aliases AS (
  SELECT DISTINCT
    public.achievement_aircraft_alias_key(value) AS alias_key,
    code AS canonical_type_key,
    manufacturer,
    display_name,
    manufacturer_family
  FROM catalog
  CROSS JOIN LATERAL unnest(ARRAY[code, display_name]) AS values(value)
  WHERE value IS NOT NULL AND btrim(value) <> ''
)
INSERT INTO public.achievement_aircraft_type_aliases (
  alias_key, canonical_type_key, manufacturer, display_name,
  manufacturer_family, simbrief_supported, is_active
)
SELECT alias_key, canonical_type_key, manufacturer, display_name,
       manufacturer_family, true, true
FROM aliases
ON CONFLICT (alias_key) DO UPDATE SET
  canonical_type_key = EXCLUDED.canonical_type_key,
  manufacturer = EXCLUDED.manufacturer,
  display_name = EXCLUDED.display_name,
  manufacturer_family = EXCLUDED.manufacturer_family,
  simbrief_supported = true,
  is_active = true,
  updated_at = now();

COMMIT;


